{
  "name": "@makcimbx/opencode-pty",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "module": "dist/index.js",
  "version": "0.6.1",
  "description": "OpenCode plugin for interactive PTY management with safe output, terminal snapshots, and reliable process waiting",
  "author": "makcimbx",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "pty",
    "pseudo-terminal",
    "terminal",
    "background-process",
    "interactive",
    "cli",
    "shell",
    "dev-server",
    "bun"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/makcimbx/opencode-pty.git"
  },
  "bugs": {
    "url": "https://github.com/makcimbx/opencode-pty/issues"
  },
  "homepage": "https://github.com/makcimbx/opencode-pty#readme",
  "files": [
    "dist"
  ],
  "license": "MIT",
  "type": "module",
  "exports": {
    "./tui": {
      "types": "./dist/src/tui/index.d.ts",
      "default": "./dist/src/tui/index.js"
    },
    "./v1": {
      "types": "./dist/src/plugin.d.ts",
      "default": "./dist/src/plugin.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./*": {
      "types": "./dist/src/*.d.ts",
      "default": "./dist/src/*.js"
    },
    "./*/*": {
      "types": "./dist/src/*/*.d.ts",
      "default": "./dist/src/*/*.js"
    },
    "./*/*/*": {
      "types": "./dist/src/*/*/*.d.ts",
      "default": "./dist/src/*/*/*.js"
    },
    "./*/*/*/*": {
      "types": "./dist/src/*/*/*/*.d.ts",
      "default": "./dist/src/*/*/*/*.js"
    }
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "unittest": "bun test",
    "test:e2e": "PW_DISABLE_TS_ESM=1 NODE_ENV=test bun --bun playwright test",
    "test:browser": "node test/browser-smoke.mjs",
    "test:all": "bun unittest && bun test:e2e",
    "build:plugin": "tsc -p tsconfig.build.json && bun x copyfiles -u 0 \"src/**/*.txt\" dist",
    "build:dev": "bun clean && bun build:plugin && vite build --mode development",
    "build:prod": "bun clean && bun build:plugin && vite build --mode production",
    "prepack": "bun build:prod",
    "clean": "rm -rf dist playwright-report test-results",
    "lint": "biome lint .",
    "lint:fix": "biome lint --write .",
    "format": "biome format .",
    "format:fix": "biome format --write ."
  },
  "devDependencies": {
    "@biomejs/biome": "2.3.13",
    "@opentui/core": "0.5.17",
    "@opentui/solid": "0.5.17",
    "@playwright/test": "1.57.0",
    "@types/bun": "^1.3.8",
    "@types/jsdom": "^27.0.0",
    "@types/react": "^18.3.27",
    "@types/react-dom": "^18.3.7",
    "@vitejs/plugin-react": "^4.7.0",
    "@xterm/addon-fit": "^0.11.0",
    "@xterm/addon-serialize": "^0.14.0",
    "@xterm/xterm": "^6.0.0",
    "happy-dom": "^20.5.0",
    "jsdom": "^27.4.0",
    "playwright-core": "1.57.0",
    "react": "^18.3.1",
    "react-dom": "^18.3.1",
    "solid-js": "1.9.12",
    "typescript": "^5.9.3",
    "vite": "^7.3.1"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.12",
    "typescript": "^5"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "engines": {
    "opencode": ">=1.18.29"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.3.13",
    "@opencode-ai/sdk": "^1.3.13",
    "@opencode/plugin": "^2.0.26",
    "@xterm/headless": "^6.0.0",
    "bun-pty": "^0.4.10",
    "open": "^11.0.0"
  }
}
